// ============================================================
//  MadridMove – central configuration of the Node-RED services
//  (collector and client are Python programs, their settings are in python/config.py)
//  Values can be overridden with environment variables, e.g. ORS_API_KEY=abc node-red
// ============================================================
const cfg = {
    // Topic prefix: set by configure.py, do not edit by hand
    prefix: 'upm-dsiot-g6/move',

    apis: {
        // openrouteservice (travel time, elevation; free key, optional)
        ors: env.get('ORS_URL') || 'https://api.openrouteservice.org',
        orsKey: env.get('ORS_API_KEY') || ''
    },

    reco: {
        // Personal limits as long as a user has not set any ("cautious")
        defaultSettings: { rain: 'none', windMax: 25, tempMin: 8, tempMax: 30 },
        rainLight: 0.1,          // mm per 15 min = light rain (limit for "no rain")
        rainHeavy: 1.0,          // mm per 15 min = heavy rain (limit for "light rain ok")

        okBikes: 3,              // a station with at least this many bikes counts as safe
        nearbyStationM: 500,     // radius for alternative stations
        altFasterMin: 5,         // warning if walking/transit is at least this much faster
        dockMin: 2,              // unlocking + docking
        minPerHmUp: 0.05,        // extra time per metre of climb (3 s; BiciMAD = e-bikes)

        windowMin: 30,           // recommendation and notifications only this many minutes before departure
        preInfoMin: 15,          // pre-departure info this many minutes before departure
        staleMin: 15,            // BiciMAD data older than this = outdated
        weatherStaleMin: 30,     // weather data older than this = outdated
        maxRoutesPerUser: 3,

        // Route profile without ORS (estimate mode) and transit estimate (no timetable)
        bikeSpeedKmh: 14,
        walkSpeedKmh: 4.8,
        detourFactor: 1.3,       // straight line -> street distance
        transitSpeedKmh: 18,
        transitAccessMin: 8,     // walking to and from the stop
        transitWaitMin: 4,       // average wait (replaced by EMT live data if available)

        // EMT bus arrivals (Python collector with credentials in python/secrets.env)
        busFreshMin: 4,          // bus data older than this is ignored
        busApplyMin: 20,         // only for trips that start within this many minutes
        walkMPerMin: 80          // walking to the stop (about 4.8 km/h)
    },

    // Statistics for the charts (tab "Statistics")
    stats: {
        center: { lat: 40.4169, lon: -3.7035 },  // Puerta del Sol
        centerRadiusKm: 3,       // up to here "centre", beyond "outskirts"
        freshMin: 20,            // only stations with data newer than this
        waveEveryMin: 5,         // fill level history: one point every 5 min
        waveKeepH: 24,           // ... for 24 h
        useEveryMin: 10,         // weather and bike use: movements per 10 min
        useKeepD: 1              // ... for 24 h (same window as the fill level)
    }
};
global.set('cfg', cfg);
node.status({
    fill: cfg.apis.orsKey ? 'green' : 'yellow', shape: 'dot',
    text: cfg.apis.orsKey ? 'ORS key set' : 'no ORS key: estimate mode'
});

