    const problems = [], hints = [], notes = [];

    // ---------- travel time ----------
    let bikeMin = (p.bike ? p.bike.min : 0) + R.dockMin;
    if (p.bike && p.bike.ascent) bikeMin += p.bike.ascent * R.minPerHmUp;   // e-bike: small extra time
    bikeMin = Math.round(bikeMin);

    // ---------- bikes at the start station ----------
    const sysB = st.system.bicimad || '';
    const bAlive = id => st.bikes[id] && ((sysB.indexOf('online') === 0) || st.bikes[id].ts > (st.sysAt.bicimad || 0));
    const fresh = id => bAlive(id) && now - st.bikes[id].ts < R.staleMin * 60000;
    const sFrom = st.bikes[p.from.id], sTo = st.bikes[p.to.id];
    let dataMissing = false, alt = null;
    const avail = s => (s && s.renting !== false) ? s.bikes : 0;
    if (planned) {
        // bikes are only assessed inside the time window
    } else if (!fresh(p.from.id)) {
        dataMissing = true;
        notes.push('BiciMAD data missing' + (sysB ? ' (' + sysB + ')' : ''));
    } else if (avail(sFrom) < R.okBikes) {
        // alternative station: nearest station within the radius with enough bikes
        const base = st.stations[p.from.id] || p.from;
        alt = Object.values(st.stations)
            .filter(s => s.id !== p.from.id && fresh(s.id) && avail(st.bikes[s.id]) >= R.okBikes)
            .map(s => ({ id: s.id, name: s.name, distM: Math.round(dist(base, s) / 10) * 10, bikes: avail(st.bikes[s.id]) }))
            .filter(s => s.distM <= R.nearbyStationM)
            .sort((a, b) => a.distM - b.distM)[0] || null;
        const n = avail(sFrom);
        const here = (n === 0 ? 'no bikes' : 'only ' + n + (n === 1 ? ' bike' : ' bikes')) + ' at ' + p.from.name;
        if (alt) hints.push(here + ' – alternative station ' + alt.name + ' (' + alt.distM + ' m, ' + alt.bikes + ' bikes)');
        else problems.push(here + ', none within ' + R.nearbyStationM + ' m either');
    }

    // ---------- weather during the trip ----------
    const startT = sch ? sch.at : now;
    let tw = tripWeather(startT, startT + bikeMin * 60000);
    if (planned && tw && tw.source !== 'forecast') {
        tw = null;                                          // departure is beyond the forecast (24 h)
        notes.push('weather preview as soon as the departure is less than 24 h away');
    } else if (!tw) {
        notes.push('weather data missing (' + (st.system.weather || 'unknown') + ')');
        if (!planned) dataMissing = true;                   // no weather, no verdict (no false all-clear)
    }
    else {
        const rainLimit = set.rain === 'none' ? R.rainLight : set.rain === 'light' ? R.rainHeavy : Infinity;
        if (tw.maxPrecip >= rainLimit) {
            const first = tw.slots.find(s => (s.precip || 0) >= rainLimit);
            const when = tw.source !== 'forecast' ? '' :
                ' expected' + (first && first.t > startT ? ' from ' + hm(first.t) : ' during the trip');
            problems.push((tw.maxPrecip >= R.rainHeavy ? 'heavy rain' : 'rain') + when +
                ' (' + num(tw.maxPrecip) + ' mm)');
        }
        if (tw.maxWind > set.windMax) problems.push('wind up to ' + Math.round(tw.maxWind) + ' km/h (your limit ' + set.windMax + ')');
        if (tw.minTemp < set.tempMin) problems.push('only ' + Math.round(tw.minTemp) + ' °C (your limit ' + set.tempMin + ' °C)');
        if (tw.maxTemp > set.tempMax) problems.push(Math.round(tw.maxTemp) + ' °C (your limit ' + set.tempMax + ' °C)');
    }

    // ---------- transit: timetable (GTFS) > EMT live > estimate ----------
    let transitMin = Math.round(p.transit.min), transitLabel = 'transit (estimate)', bus = null, plan = null, noTransit = false;
    const leaveIn = sch ? sch.minutesLeft : 0;
    const b = st.bus[key];
    let arr = [];
    const walk = a => Math.ceil(((a.distM != null ? a.distM : (b && b.stop.distM)) || 0) / R.walkMPerMin);
    if (b && b.stop && now - b.ts < R.busFreshMin * 60000) {
        // live arrivals at up to 3 nearby stops (subtract the minutes since they were fetched)
        const elapsed = Math.floor((now - b.ts) / 60000);
        arr = (b.arrivals || []).map(a => Object.assign({}, a, { min: a.min - elapsed })).filter(a => a.min >= 0);
        bus = { stop: b.stop.name, distM: b.stop.distM, walkMin: walk(b.stop),
            next: arr.slice(0, 4).map(a => ({ line: a.line, min: a.min, destination: a.destination, stop: a.stop || b.stop.name })) };
    }
    // timetable: only if it was computed for exactly this departure
    const pl = st.plan[key];
    if (pl && (sch ? Math.abs(pl.depAt - sch.at) < 90000 : !pl.forDeparture && now - pl.depAt < 15 * 60000)) {
        plan = { status: pl.status, line: pl.line, headsign: pl.headsign, board: pl.board, alight: pl.alight,
            boardAt: pl.boardAt, headwayMin: pl.headwayMin, waitMin: pl.waitMin, rideMin: pl.rideMin, totalMin: pl.totalMin };
        if (pl.status === 'ok') { transitMin = pl.totalMin; transitLabel = 'transit (timetable)'; }
        else if (pl.status === 'noservice') { noTransit = true; }
        // 'nodirect': no direct line -> the estimate stays (maybe possible with a transfer)
    }
    if (bus && leaveIn <= R.busApplyMin) {
        const norm = x => String(x).replace(/^0+(?=.)/, '').toUpperCase();
        if (plan && plan.status === 'ok') {
            // timetable line live at the stop? Then the real instead of the planned waiting time
            const live = arr.find(a => norm(a.line) === norm(plan.line) && a.min >= leaveIn + plan.board.walkMin);
            if (live) {
                const wait = live.min - leaveIn - plan.board.walkMin;
                transitMin = Math.round(plan.board.walkMin + wait + plan.rideMin + plan.alight.walkMin);
                transitLabel = 'transit (timetable + EMT live)';
                bus.used = { line: live.line, min: live.min, wait: wait, stop: live.stop || b.stop.name };
            }
        } else if (!plan) {
            // no timetable: next reachable bus, ride time estimated
            const catchable = arr.find(a => a.min >= leaveIn + walk(a));
            if (catchable) {
                const wait = catchable.min - leaveIn - walk(catchable);
                transitMin = Math.round(p.transit.min - R.transitWaitMin - R.transitAccessMin / 2 + walk(catchable) + wait);
                transitLabel = 'transit (EMT live)';
                bus.used = { line: catchable.line, min: catchable.min, wait: wait, stop: catchable.stop || b.stop.name };
            }
        }
    }

    // ---------- alternatives ----------
    const alternatives = [{ mode: 'walk', label: 'walking', min: Math.round(p.walk.min) }];
    if (!noTransit) alternatives.push({ mode: 'transit', label: transitLabel, min: transitMin });
    alternatives.sort((a, b) => a.min - b.min);
    const faster = alternatives.find(a => a.min <= bikeMin - R.altFasterMin);
    if (faster) problems.push(faster.label.replace(/ \(.*\)/, '') + ' is ' + (bikeMin - faster.min) +
        ' min faster (' + faster.min + ' instead of ' + bikeMin + ' min)');

    // ---------- result ----------
    const status = planned ? 'planned' : dataMissing ? 'unknown' : (problems.length ? 'warn' : 'ok');
    // planned: possible problems only as a preview, without a verdict
    const preview = planned ? problems.splice(0) : [];
    const weatherText = !tw ? 'weather unknown' :
        (tw.maxPrecip < R.rainLight ? 'dry' : 'rain up to ' + num(tw.maxPrecip) + ' mm') + ', ' +
        (tw.minTemp === tw.maxTemp || Math.round(tw.minTemp) === Math.round(tw.maxTemp) ? Math.round(tw.maxTemp) + ' °C'
            : Math.round(tw.minTemp) + '–' + Math.round(tw.maxTemp) + ' °C') +
        ', wind ' + Math.round(tw.maxWind) + ' km/h';
    const bikesText = sFrom ? avail(sFrom) + (avail(sFrom) === 1 ? ' bike' : ' bikes') + ' at ' + p.from.name : '';
    const tr = alternatives.find(a => a.mode === 'transit');
    const altText = (tr ? 'transit approx. ' + tr.min + ' min' : 'no bus at this time') + ', walking ' +
        alternatives.find(a => a.mode === 'walk').min + ' min';
    const headline = status === 'ok' ? '✓ Bike is fine' : status === 'warn' ? '⚠ Better not by bike today'
        : status === 'planned' ? '🕒 Planned · recommendation from ' + hm(windowStart) : '? Data missing';
    const detail = status === 'planned' ? ['departure ' + sch.nextText,
            'approx. ' + bikeMin + ' min by bike', tw ? 'preview: ' + weatherText : null,
            preview.length ? 'forecast: ' + preview.join(', ') : null].filter(Boolean).join(' · ')
        : status === 'ok' ? [alt ? hints[0] : bikesText, weatherText, 'approx. ' + bikeMin + ' min'].filter(Boolean).join(' · ')
        : status === 'warn' ? problems.join(' · ') + '. Alternatives: ' + altText + (hints.length ? '. ' + hints[0] : '')
        : notes.join(' · ');
    return {
        user: p.user, route: p.route, name: p.name, from: p.from.name, to: p.to.name,
        status: status, headline: headline, detail: detail,
        problems: problems, preview: preview, hints: hints, notes: notes, alternatives: alternatives,
        bike: { min: bikeMin, bikes: (sFrom && !planned) ? avail(sFrom) : null, docks: (sTo && !planned) ? sTo.docks : null, alt: alt },
        bus: bus,
        plan: plan,
        weather: tw ? { text: weatherText, source: tw.source,
            from: hm(startT), to: hm(startT + bikeMin * 60000) } : null,
        settings: set,
        departure: dep ? { time: dep.time, days: dep.days, text: daysText(dep.days) + ' ' + dep.time } : null,
        nextDeparture: sch ? new Date(sch.at).toISOString() : null,
        nextDepartureText: sch ? sch.nextText : null,
        inWindow: !!(sch && sch.inWindow),
        windowStart: windowStart ? new Date(windowStart).toISOString() : null,
        windowStartText: windowStart ? hm(windowStart) : null,
        windowStartLabel: windowStart ? dayLabel(windowStart) + ' ' + hm(windowStart) : null,
        minutesLeft: sch ? sch.minutesLeft : null,
        _sch: sch,
        updated: new Date().toISOString()
    };
}

// debounce: several updates in quick succession -> compute once after 1 s
const pending = context.get('pending') || {};
affected.forEach(k => { pending[k] = true; });
context.set('pending', pending);
context.set('st', st);
if (!context.get('timer')) {
    context.set('timer', true);
    setTimeout(flushPending, 1000);
}
return null;

function flushPending() {
    context.set('timer', false);
    const keys = Object.keys(context.get('pending') || {});
    context.set('pending', {});
    st = context.get('st');
    const out = [];
    for (const key of keys) {
        const p = st.profiles[key];
        if (!p) continue;
        const r = evaluate(key, p);
        const sch = r._sch;
        delete r._sch;
        const prev = st.last[key];
        // only send if the content has changed (without timestamps/minutes)
        // (destination docks and alternative-station details are not on the card -> not compared)
        const sig = JSON.stringify([r.status, r.detail, r.problems, r.preview, r.hints, r.notes, r.alternatives,
            r.bike.min, r.bike.bikes, r.bus, r.plan, r.weather, r.settings, r.departure, r.nextDeparture, r.inWindow]);
        if (!prev || prev.sig !== sig) out.push({ topic: P + '/reco/' + key, payload: r, qos: 1, retain: true });

        // ---------- notifications ----------
        const occKey = sch ? key + '|' + sch.occurrence : null;
        const occ = occKey ? (st.occ[occKey] = st.occ[occKey] || { t: Date.now() }) : null;
        const head = '"' + r.name + '" (' + r.from + ' → ' + r.to + (sch ? ', ' + r.departure.time : '') + ')';
        let text = null;
        if (st.fresh[key] && !prev) {
            text = 'Route "' + r.name + '" (' + r.from + ' → ' + r.to + ') saved: ' +
                (r.departure ? r.departure.text : 'no departure time') +
                '. Recommendation and notifications from ' + R.windowMin + ' min before departure' +
                (r.status === 'planned' ? ' (' + r.windowStartLabel + ')' : '') + '.';
        }
        delete st.fresh[key];
        if (sch && sch.inWindow && r.status !== 'unknown') {
            const msgOk = '✓ Bike is fine for ' + head + ': ' + r.detail + '.';
            const msgWarn = '⚠ Better not by bike today for ' + head + ': ' + r.detail + '.';
            let add = null;
            if (r.status === 'warn' && !occ.warned) {
                add = msgWarn; occ.warned = true; occ.pre = occ.pre || sch.minutesLeft <= R.preInfoMin;
            } else if (r.status === 'ok' && occ.warned) {
                add = '✓ All clear for ' + head + ': the bike is fine again. ' + r.detail + '.';
                occ.warned = false; occ.pre = occ.pre || sch.minutesLeft <= R.preInfoMin;
            } else if (!occ.pre && sch.minutesLeft <= R.preInfoMin) {
                add = (r.status === 'ok' ? msgOk : msgWarn) + ' Departure in ' + sch.minutesLeft + ' min.';
                occ.pre = true;
            }
            if (add) text = text ? text + ' ' + add : add;
        }
        if (text) out.push({ topic: P + '/alerts/' + p.user, payload: text, qos: 1, retain: false });
        st.last[key] = { sig: sig, status: r.status };
    }
    for (const k of Object.keys(st.occ)) if (Date.now() - st.occ[k].t > 2 * 86400000) delete st.occ[k];
    context.set('st', st);
    node.status({ fill: 'green', shape: 'dot', text: Object.keys(st.profiles).length + ' routes, ' + out.length +
        ' messages, ' + new Date().toLocaleTimeString('en-GB', { timeZone: 'Europe/Madrid' }) });
    if (out.length) node.send([out]);
}

// .../reco/+/+ -> data for the route cards (one card per route)
const cfg = global.get('cfg');
let recos = flow.get('recos');
if (!recos || recos.__prefix !== cfg.prefix) recos = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty || typeof msg.payload !== 'object') delete recos[key];
else recos[key] = msg.payload;
flow.set('recos', recos);
const routes = Object.keys(recos).filter(k => k !== '__prefix').sort().map(k => {
    const r = recos[k];
    return {
        key: k, user: r.user, name: r.name, from: r.from, to: r.to,
        status: r.status, headline: r.headline,
        problems: r.problems || [], preview: r.preview || [], hints: r.hints || [], notes: r.notes || [],
        alternatives: r.alternatives || [], bike: r.bike || {}, bus: r.bus || null, plan: r.plan || null, weather: r.weather,
        settings: r.settings, departureText: r.departure ? r.departure.text : null,
        nextDeparture: r.nextDeparture, nextDepartureText: r.nextDepartureText, windowStartText: r.windowStartText || null,
        windowMin: cfg.reco.windowMin
    };
});
return { payload: { routes: routes } };

// Forms "New route" and "My settings". Every field sends with its own msg.topic.
// Output 1: MQTT (route, settings, delete) | 2: route status | 3: settings status
const cfg = global.get('cfg');
const P = cfg.prefix;
const D = cfg.reco.defaultSettings;
const f = flow.get('form') || {};
const slug = s => String(s || '').toLowerCase().normalize('NFD')
    .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '').slice(0, 30);
const save = () => flow.set('form', f);
const stationName = id => ((flow.get('stations') || []).find(s => s.id === id) || {}).name;

switch (msg.topic) {
    case 'user': f.user = msg.payload; break;
    case 'name': f.name = msg.payload; break;
    case 'from': f.from = msg.payload; break;
    case 'to': f.to = msg.payload; break;
    case 'time': f.time = msg.payload; break;
    case 'days': f.days = (Array.isArray(msg.payload) ? msg.payload : [msg.payload]).map(Number).filter(Boolean); break;
    case 'rain': f.rain = msg.payload; break;
    case 'windMax': f.windMax = Number(msg.payload); break;
    case 'tempMin': f.tempMin = Number(msg.payload); break;
    case 'tempMax': f.tempMax = Number(msg.payload); break;
    case 'delSel': f.del = msg.payload; break;
    case 'create': {
        const u = slug(f.user), r = slug(f.name);
        if (!u || !r) return [null, { payload: '⚠ Please enter your name above and a route name.' }, null];
        const a = stationName(f.from), b = stationName(f.to);
        if (!a || !b) return [null, { payload: '⚠ Please select a start and a destination station.' }, null];
        if (f.from === f.to) return [null, { payload: '⚠ Start and destination are the same station.' }, null];
        if (!/^\d{1,2}:\d{2}$/.test(String(f.time || ''))) return [null, { payload: '⚠ Please enter a departure time (e.g. 08:30).' }, null];
        if (!f.days || !f.days.length) return [null, { payload: '⚠ Please choose at least one weekday.' }, null];
        const mine = Object.keys(flow.get('routeKeys') || {}).filter(k => k.split('/')[0] === u && k !== u + '/' + r);
        if (mine.length >= cfg.reco.maxRoutesPerUser) return [null, { payload: '⚠ At most ' + cfg.reco.maxRoutesPerUser + ' routes per user.' }, null];
        save();
        const time = String(f.time).padStart(5, '0');
        const route = { name: f.name, from: { id: f.from, label: a }, to: { id: f.to, label: b },
            departure: { time: time, days: f.days.slice().sort() }, createdAt: new Date().toISOString() };
        return [{ topic: P + '/routes/' + u + '/' + r, payload: route, qos: 1, retain: true },
            { payload: '✔ Route ' + u + '/' + r + ' saved: ' + a + ' → ' + b + ', ' + time + '.' }, null];
    }
    case 'saveSettings': {
        const u = slug(f.user);
        if (!u) return [null, null, { payload: '⚠ Please enter your name above.' }];
        const s = {
            rain: ({ kein: 'none', leicht: 'light', egal: 'any' })[f.rain] || f.rain || D.rain,
            windMax: isFinite(f.windMax) && f.windMax > 0 ? f.windMax : D.windMax,
            tempMin: isFinite(f.tempMin) ? f.tempMin : D.tempMin,
            tempMax: isFinite(f.tempMax) ? f.tempMax : D.tempMax
        };
        if (s.tempMin >= s.tempMax) return [null, null, { payload: '⚠ The minimum temperature must be below the maximum temperature.' }];
        save();
        const rainText = { none: 'no rain', light: 'light rain ok', any: 'rain does not matter' }[s.rain];
        return [{ topic: P + '/users/' + u + '/settings', payload: s, qos: 1, retain: true }, null,
            { payload: '✔ Saved for ' + u + ': ' + rainText + ', wind up to ' + s.windMax + ' km/h, ' + s.tempMin + ' to ' + s.tempMax + ' °C.' }];
    }
    case 'delete': {
        if (!f.del) return [null, { payload: '⚠ Please choose a route to delete.' }, null];
        const key = f.del;
        f.del = null;
        save();
        // empty retained message = delete the stored route on the broker
        return [{ topic: P + '/routes/' + key, payload: '', qos: 1, retain: true },
            { payload: '🗑 Route ' + key + ' deleted.' }, null];
    }
}
save();
return null;

// .../routes/+/+ -> list of all routes (for "Delete route" and the limit per user)
const cfg = global.get('cfg');
let routes = flow.get('routeKeys');
if (!routes || routes.__prefix !== cfg.prefix) routes = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete routes[key];
else if (typeof msg.payload === 'object') routes[key] = msg.payload.name || key;
flow.set('routeKeys', routes);
const options = Object.keys(routes).filter(k => k !== '__prefix').sort().map(k => ({ label: k + ' – ' + routes[k], value: k }));
return { ui_update: { options: options.length ? options : [{ label: '(no routes)', value: '' }] } };

// .../system/+ -> table "Data sources"
const cfg = global.get('cfg');
let rows = context.get('rows');
if (!rows || rows.__prefix !== cfg.prefix) rows = { __prefix: cfg.prefix };
const name = msg.topic.split('/').pop();
const empty = msg.payload === '' || msg.payload == null || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete rows[name];          // empty retained message = source not set up (any more)
else rows[name] = {
    'Source': name,
    'Status': String(msg.payload),
