};
context.set('rows', rows);
return { payload: Object.keys(rows).filter(k => k !== '__prefix').map(k => rows[k]) };

// .../live/weather -> text line: current weather + rain in the forecast (next 2 h)
const w = msg.payload;
if (typeof w !== 'object' || w == null) return null;
const hm = ms => new Date(ms).toLocaleTimeString('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
const rain = (w.forecast || []).filter(f => f.t <= Date.now() + 2 * 3600000 && f.precip >= 0.1);
const fc = !(w.forecast || []).length ? '' : rain.length ? ' · rain expected from ' + hm(rain[0].t) : ' · next 2 h dry';
return { payload: w.temp + ' °C · ' + w.precip + ' mm · Wind ' + w.wind + ' km/h' + fc +
    ' · as of ' + hm(w.ts) };

// Demo route (page "System & demo"): a real route "To university" (Sol -> Ciudad Universitaria)
// for the user "demo", departure in 14 min (so immediately inside the window for notifications).
// The settings of "demo" are reset to the defaults so that every rehearsal starts the same way.
// The stations are found by location (nearest BiciMAD station to Sol and to Ciudad Universitaria).
// Output 1: MQTT   Output 2: text in the field "Demo route status"
const cfg = global.get('cfg');
const P = cfg.prefix;
if (msg.topic !== 'demoroutes') return null;
const stations = flow.get('stations') || [];
if (!stations.length) {
    const t = '⚠ No station list yet. Is collector.py running (window open, "connected")? Without internet it uses stations_cache.json.';
    node.warn(t);
    return [null, { payload: t }];
}
const dist = (a, b) => Math.hypot((a.lon - b.lon) * 85000, (a.lat - b.lat) * 111000);
const near = (lat, lon) => stations.slice().sort((a, b) => dist(a, { lat, lon }) - dist(b, { lat, lon }))[0];
const parts = {};
new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false })
    .formatToParts(new Date(Date.now() + 14 * 60000)).forEach(p => { parts[p.type] = p.value; });
const time = String(Number(parts.hour) % 24).padStart(2, '0') + ':' + parts.minute;
const a = near(40.4169, -3.7035), b = near(40.4437, -3.7276);          // Sol -> Ciudad Universitaria
const out = [
    { topic: P + '/users/demo/settings', payload: cfg.reco.defaultSettings, qos: 1, retain: true },
    { topic: P + '/routes/demo/zur-uni', payload: '', qos: 1, retain: true },     // demo route of older versions
    { topic: P + '/routes/demo/to-university', qos: 1, retain: true,
      payload: { name: 'To university', from: { id: a.id, label: a.name }, to: { id: b.id, label: b.name },
          departure: { time: time, days: [1, 2, 3, 4, 5, 6, 7] }, createdAt: new Date().toISOString() } }
];
return [out, { payload: 'Demo route "To university" created (' + a.name + ' → ' + b.name + '), departure ' + time + ' (in 14 min).' }];

// On start: write defaults into the form (departure 08:30, Mon–Fri, cautious limits)
const D = global.get('cfg').reco.defaultSettings;
const f = flow.get('form') || {};
f.time = f.time || '08:30';
f.days = (f.days && f.days.length) ? f.days : [1, 2, 3, 4, 5];
f.rain = ({ kein: 'none', leicht: 'light', egal: 'any' })[f.rain] || f.rain || D.rain;
f.windMax = f.windMax || D.windMax;
f.tempMin = isFinite(f.tempMin) ? f.tempMin : D.tempMin;
f.tempMax = isFinite(f.tempMax) ? f.tempMax : D.tempMax;
flow.set('form', f);
return [{ payload: f.time }, { payload: f.days }, { payload: f.rain }, { payload: f.windMax },
    { payload: f.tempMin }, { payload: f.tempMax }];

// .../static/stations (retained) -> selection lists for start and destination station.
// The lists are "comboboxes": typing filters, e.g. "sol" or the station number.
const list = Array.isArray(msg.payload) ? msg.payload : [];
flow.set('stations', list);
const options = list.map(s => ({ label: s.name + ' (' + s.id + ')', value: s.id }));
node.status({ fill: 'green', shape: 'dot', text: list.length + ' stations' });
return { ui_update: { options: options.length ? options : [{ label: '(loading …)', value: '' }] } };

// ============================================================
//  Statistics service: key figures for the dashboard charts
//  Inputs (wildcard subscriptions):
//    .../static/stations      location and capacity of the stations
//    .../live/bicimad/+       bikes/docks per station
//    .../live/weather         current weather
//    .../stats/history        own history (retained) -> taken over after a restart
//    tick every minute
//  Outputs (retained):
//    .../stats/now            current figures (free bikes, empty/full stations, movements)
//    .../stats/spatial        per station: distance to Puerta del Sol and fill level
//    .../stats/history        history: fill level (every 5 min) and weather/use (every 10 min)
//
//  Fill level of a station = bikes / (bikes + free docks)
//  Bike movements = sum of all changes in the number of bikes (rentals + returns)
// ============================================================
const cfg = global.get('cfg');
const P = cfg.prefix, S = cfg.stats;
let st = context.get('st');
if (!st || st.prefix !== P || st.v !== 2) {
    st = { v: 2, prefix: P, stations: {}, bikes: {}, moves: 0, weather: null, restored: false,
        hist: { wave: [], use: [] }, lastWave: 0, lastUse: Date.now(), lastSpatial: '' };
}
const t = msg.topic || '';
const p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
const out = [];

// distance in km (approximation, good enough within a city)
const distKm = (a, b) => Math.hypot((a.lon - b.lon) * 111.32 * Math.cos(a.lat * Math.PI / 180), (a.lat - b.lat) * 110.54);

if (t.endsWith('/static/stations') && Array.isArray(p)) {
    st.stations = {};
    for (const s of p) {
        const d = distKm(s, S.center);
        st.stations[s.id] = { distKm: Math.round(d * 100) / 100, zone: d <= S.centerRadiusKm ? 'center' : 'edge' };
    }
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (empty || typeof p !== 'object') return null;
    const id = t.split('/').pop();
    const prev = st.bikes[id];
    // retain=true = delivered by the broker (initial state), not a real movement
    if (prev && !msg.retain) st.moves += Math.abs((p.bikes || 0) - prev.bikes);
    st.bikes[id] = { bikes: p.bikes || 0, docks: p.docks || 0, ts: p.ts || Date.now() };
} else if (t.endsWith('/live/weather')) {
    if (empty || typeof p !== 'object') return null;
    st.weather = { temp: p.temp, precip: p.precip, wind: p.wind, ts: p.ts };
} else if (t.endsWith('/stats/history')) {
    // only once after start: take over the stored history (afterwards these are our own messages)
    if (!st.restored && !empty && typeof p === 'object') {
        st.hist = { wave: Array.isArray(p.wave) ? p.wave : [], use: Array.isArray(p.use) ? p.use : [] };
        const lw = st.hist.wave[st.hist.wave.length - 1];
        if (lw) st.lastWave = lw.t;
        node.warn('History restored: ' + st.hist.wave.length + ' fill-level points, ' + st.hist.use.length + ' weather/use points');
    }
    st.restored = true;
    context.set('st', st);
    return null;
}

// ---------- evaluation only on the tick (every minute) ----------
if (t !== 'tick') { context.set('st', st); return null; }
st.restored = true;                        // from now on at the latest: no later overwriting
const now = Date.now();

// current situation: only stations with fresh data
const fresh = Object.keys(st.bikes).filter(id => st.stations[id] && now - st.bikes[id].ts < S.freshMin * 60000);
const zone = { center: { b: 0, slots: 0 }, edge: { b: 0, slots: 0 } };
let total = 0, emptySt = 0, fullSt = 0;
const points = [];
for (const id of fresh) {
    const b = st.bikes[id], s = st.stations[id];
    const slots = b.bikes + b.docks;
    total += b.bikes;
    if (b.bikes === 0) emptySt++;
    if (b.docks === 0) fullSt++;
    if (slots > 0) {
        zone[s.zone].b += b.bikes; zone[s.zone].slots += slots;
        points.push([s.distKm, Math.round(b.bikes / slots * 100)]);
    }
}
const pct = z => z.slots ? Math.round(z.b / z.slots * 1000) / 10 : null;
if (!fresh.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no fresh BiciMAD data (is collector.py running?)' });
    context.set('st', st);
    return null;
}

// centre vs outskirts (snapshot, only sent when something changed)
const sig = JSON.stringify(points);
if (sig !== st.lastSpatial) {
    st.lastSpatial = sig;
    out.push({ topic: P + '/stats/spatial', qos: 0, retain: true,
        payload: { points: points, centerRadiusKm: S.centerRadiusKm, ts: now } });
}

let histChanged = false;
// fill level history: one point every S.waveEveryMin minutes
if (now - st.lastWave >= S.waveEveryMin * 60000 - 5000) {
    st.lastWave = now;
    st.hist.wave.push({ t: now, center: pct(zone.center), edge: pct(zone.edge), total: total });
    st.hist.wave = st.hist.wave.filter(w => now - w.t <= S.waveKeepH * 3600000);
    histChanged = true;
}
// weather and bike use: one point every S.useEveryMin minutes (movements in the interval + weather)
const movesNow = st.moves;
if (now - st.lastUse >= S.useEveryMin * 60000 - 5000) {
    const w = st.weather && now - st.weather.ts < 30 * 60000 ? st.weather : null;
    if (w) st.hist.use.push({ t: now, moves: st.moves, temp: w.temp, precip: w.precip, wind: w.wind });
    st.hist.use = st.hist.use.filter(u => now - u.t <= S.useKeepD * 86400000);
    st.moves = 0;
    st.lastUse = now;
    histChanged = true;
}
if (histChanged) out.push({ topic: P + '/stats/history', qos: 1, retain: true, payload: st.hist });

out.push({ topic: P + '/stats/now', qos: 0, retain: true, payload: {
    stations: fresh.length, bikes: total, empty: emptySt, full: fullSt,
    center: pct(zone.center), edge: pct(zone.edge),
    movesSoFar: movesNow, movesWindowMin: S.useEveryMin, ts: now } });

context.set('st', st);
node.status({ fill: 'green', shape: 'dot', text: fresh.length + ' stations, ' + total + ' bikes, centre ' +
    pct(zone.center) + ' %, outskirts ' + pct(zone.edge) + ' %' });
return [out];

// Key figures "Madrid now" (page "Statistics", top)
//   .../stats/now   bikes, empty/full stations, fill level centre/outskirts
//   .../live/weather  current weather + rain in the next hour
//   .../system/+    status of the data sources (birth / close / Last Will)
//   .../stats/history  last value "bike movements per 10 min"
const cfg = global.get('cfg');
let k = context.get('k');
if (!k || k.prefix !== cfg.prefix) k = { prefix: cfg.prefix, now: null, weather: null, system: {}, moves: null };
const t = msg.topic || '', p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
if (t.endsWith('/stats/now') && !empty) k.now = p;
else if (t.endsWith('/live/weather') && !empty) k.weather = p;
else if (t.indexOf('/system/') >= 0) k.system[t.split('/').pop()] = empty ? null : String(p);
else if (t.endsWith('/stats/history') && !empty) {
    const u = (p.use || []).slice(-1)[0];
    k.moves = u ? { moves: u.moves, t: u.t } : null;
}
context.set('k', k);

const hm = ms => new Date(ms).toLocaleTimeString('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
const num = x => x == null ? '–' : String(Math.round(x * 10) / 10);
const fmt = n => n == null ? '–' : String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
let weather = null;
if (k.weather) {
    const w = k.weather;
    const next = (w.forecast || []).filter(f => f.t + 15 * 60000 > Date.now() && f.t <= Date.now() + 3600000);
    const maxP = next.length ? Math.max(...next.map(f => f.precip || 0)) : null;
    const rainAt = next.find(f => (f.precip || 0) >= 0.1);
    weather = { temp: num(w.temp), wind: Math.round(w.wind), precipNow: num(w.precip),
        now: (w.precip || 0) >= 0.1 ? 'rain' : 'dry',
        nextHour: maxP == null ? 'no forecast' : rainAt ? 'rain from ' + hm(rainAt.t) + ' (up to ' + num(maxP) + ' mm)' : 'next hour dry',
        at: hm(w.ts) };
}
const names = { bicimad: 'BiciMAD', weather: 'Weather', timetable: 'Timetable', emt: 'EMT bus' };
const sources = ['bicimad', 'weather', 'timetable', 'emt'].map(n => {
    const s = k.system[n];
    return { name: names[n], state: !s ? 'off' : s.indexOf('online') === 0 ? 'ok' : 'missing', text: s || (n === 'emt' ? 'not set up' : 'never reported') };
});
const n = k.now;
return { payload: {
    weather: weather,
    bikes: n ? { total: fmt(n.bikes), stations: n.stations, empty: n.empty, full: n.full,
        center: num(n.center), edge: num(n.edge), at: hm(n.ts) } : null,
    moves: k.moves ? { value: fmt(k.moves.moves), at: hm(k.moves.t) } : null,
    sources: sources,
    collectorDown: sources[0].state !== 'ok'
} };

// Statistics -> charts (the charts are replaced completely every time: action "replace")
//   .../stats/history -> 1: fill level centre/outskirts  3: bike movements  4: rain  5: temperature and wind
//   .../stats/spatial -> 2: centre vs outskirts
// The series are properties of each point ({x, Centre, Outskirts}); in the chart node
// "Series" is a fixed JSON list -> colours and legend order stay stable.
// The three charts under "Weather and bike use" get the same fixed left margin, so their time axes line up.
const t = msg.topic || '', p = msg.payload;
if (p == null || typeof p !== 'object') return null;
const r1 = x => x == null ? null : Math.round(x * 10) / 10;
const aligned = { chartOptions: { grid: { left: 48, right: 16, bottom: 26, containLabel: false, outerBoundsMode: 'none' } } };
const m = (arr, align) => Object.assign({ payload: arr.length ? arr : [], action: 'replace' }, align ? { ui_update: aligned } : {});
if (t.endsWith('/stats/history')) {
    // draw only from 2 points on (a single point distorts the time axis)
    const wave = (p.wave || []).length < 2 ? [] : p.wave.map(w => ({ x: w.t, Centre: w.center, Outskirts: w.edge }));
    const use = p.use || [];
    const moves = use.map(u => ({ x: u.t, 'Bike movements': u.moves }));
    const rain = use.map(u => ({ x: u.t, 'Rain (mm)': r1(u.precip || 0) }));
    const temp = use.map(u => ({ x: u.t, 'Temperature (°C)': r1(u.temp), 'Wind (km/h)': r1(u.wind) }));
    return [m(wave), null, m(moves, true), m(rain, true), m(temp, true)];
}
if (t.endsWith('/stats/spatial')) {
    const pts = (p.points || []).map(a => a[0] <= p.centerRadiusKm ? { x: a[0], Centre: a[1] } : { x: a[0], Outskirts: a[1] });
    return [null, m(pts), null, null, null];
}
return null;
